// #region 🔖Renderer
// [🔬coda🖱️desktop💻renderer🔖renderer](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer)
// Electron renderer process that mounts the coda dashboard React app with window controls.
// MUST resolve the user identity before rendering the dashboard.
// MUST communicate with coda MCP server via the preload bridge.

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";

import { Tree, TreeItem, useCommandHotkey, useMediaQuery } from "../../elements/ui";

import "./globals.css";

// #region 🔖Types
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types)
// TypeScript interfaces for coda domain models used in the renderer.
// Types MUST match the coda MCP server data structures.

declare global {
  interface Window {
    windowControls: {
      minimize(): Promise<void>;
      maximize(): Promise<void>;
      close(): Promise<void>;
    };
    os: {
      getUserId(): Promise<string>;
    };
    coda: {
      call(method: string, params?: Record<string, unknown>): Promise<McpResponse>;
      fetch(uri: string): Promise<McpResponse>;
      tool(name: string, args: Record<string, unknown>): Promise<McpResponse>;
      getConnectionStatus(): Promise<boolean>;
      onEvent(callback: (event: CodaEvent) => void): () => void;
      onConnectionStatus(callback: (connected: boolean) => void): () => void;
    };
    dialog: {
      openFolder(): Promise<string | null>;
    };
    project: {
      getPath(): Promise<string | null>;
      open(folder: string): Promise<{ success: boolean; error?: string }>;
      create(name: string, folder: string): Promise<{ success: boolean; error?: string }>;
    };
  }
}

/**
 * An event pushed from the coda sidecar process.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️codaevent](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/CodaEvent)
 *MUST have event kind, data, and timestamp.
 **/
interface CodaEvent {
  event: string;
  data: Record<string, unknown>;
  timestamp: number;
}

/**
 * MCP JSON-RPC response wrapper.

// #region 🔖Header
// [🔬coda🖱️desktop⚙️viterendererconfig](repo://p/r/coda/b/u/desktop/f/vite.renderer.config.ts)

// 2026 Ueli Saluz <ueli@semio-tech.de>

// This program is free software: you can redistribute it and/or modify
// it under the terms of the GNU Affero General Public License as
// published by the Free Software Foundation, either version 3 of the
// License, or (at your option) any later version.
// This program is distributed in the hope that it will be useful,
// but WITHOUT ANY WARRANTY; without even the implied warranty of
// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
// GNU Affero General Public License for more details.
// You should have received a copy of the GNU Affero General Public License
// along with this program.  If not, see <https://www.gnu.org/licenses/>.

// Vite build configuration for the Electron renderer process.
// Pre-bundles all dependencies from elements.tsx to prevent module waterfall
// stalls in Electron's HTTP/1.1 connection-limited renderer.

// #endregion 🔖Header

// #region 🔖Configuration
// [🔬coda🖱️desktop⚙️viterendererconfig🔖configuration](repo://p/r/coda/b/u/desktop/f/vite.renderer.config.ts/s/Configuration)
// Vite configuration for the Electron renderer process with React and Tailwind.
// Configuration MUST enable the React and Tailwind CSS plugins.
// Configuration MUST pre-bundle heavy dependencies to avoid white screen in Electron.

import type { UserConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";
import path from "path";

const configuration: UserConfig = {
  server: {
    // Pre-transform the renderer entry so all modules are cached before
    // Electron requests them. Without this, cold starts produce a white screen
    // because Electron's Chromium has a 6-connection-per-origin HTTP/1.1 limit
    // and the 80+ ESM module waterfall from elements.tsx stalls.
    warmup: {
      clientFiles: ["./renderer.tsx"],
    },
    // Allow serving files from the entire monorepo since elements.tsx and
    // other dependencies live outside the desktop project root.
    fs: {
      allow: [path.resolve(__dirname, "../..")],
    },
  },
  optimizeDeps: {
    // Pre-bundle all third-party dependencies imported by elements.tsx into
    // single chunks. This reduces the number of HTTP requests from 80+ to ~35
    // pre-bundled files, preventing connection pool exhaustion in Electron.
    // List ALL third-party dependencies to prevent Vite from discovering new
    // deps at runtime, which triggers re-optimization and invalidates the
    // module graph mid-load — causing the white screen in Electron.
    include: [
      "react",
      "react-dom",
      "react-dom/client",
      "react/jsx-runtime",
      "react/jsx-dev-runtime",
      "@dnd-kit/core",
      "@dnd-kit/sortable",
      "@dnd-kit/utilities",
      "@mdx-js/react",
      "@radix-ui/react-accordion",
      "@radix-ui/react-avatar",
      "@radix-ui/react-collapsible",
      "@radix-ui/react-dialog",
      "@radix-ui/react-dropdown-menu",
      "@radix-ui/react-hover-card",
      "@radix-ui/react-popover",
      "@radix-ui/react-scroll-area",
