    // deps at runtime, which triggers re-optimization and invalidates the
    // module graph mid-load — causing the white screen in Electron.
    include: [
      "react",
      "react-dom",
      "react-dom/client",
      "react/jsx-runtime",
      "react/jsx-dev-runtime",
      "@dnd-kit/core",
