      "@radix-ui/react-toggle-group",
      "@radix-ui/react-tooltip",
      "@react-three/drei",
      "@react-three/fiber",
      "@xstate/react",
      "@xyflow/react",
      "class-variance-authority",
      "clsx",
      "cmdk",
      "d3-force",
      "dagre",
      "date-fns",
      "date-fns/locale",
      "fuse.js",
      "i18next",
