/**
 * Project configuration from .coda/project.json.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️project](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Project)
 *MUST have design and targets.
 **/
interface Project {
