// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖statusbadge](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/StatusBadge)

/**
 * Displays a colored badge for compliance status.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖components🔖statusbadge🛠️statusbadge](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Components/s/StatusBadge/d/i/StatusBadge)
 *MUST render green for compliant, red for violated, gray for unknown.
 **/
function StatusBadge({ status }: { status?: string }) {
  const colors: Record<string, string> = {
    compliant: "bg-success-bg text-success-foreground border-success-border",
    violated: "bg-destructive-bg text-destructive-foreground border-destructive-border",
