  const compliantCount = useMemo(() => {
    if (!report?.validations) return 0;
    return report.validations.filter((v) => v.truth === "true").length;
  }, [report]);

  const totalPropertyCount = useMemo(() => (properties ? countProperties(properties) : 0), [properties]);

