            <Card title={`Properties (${totalPropertyCount})`}>
              <div className="space-y-1">
                {properties.map((prop) => (
                  <div key={prop.id} className="flex items-start gap-2 rounded px-2 py-1.5 text-sm hover:bg-hover-window">
