/**
 * An event pushed from the coda sidecar process.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️codaevent](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/CodaEvent)
 *MUST have event kind, data, and timestamp.
 **/
interface CodaEvent {
  event: string;
  data: Record<string, unknown>;
  timestamp: number;
}

/**
 * MCP JSON-RPC response wrapper.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️mcpresponse](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/McpResponse)
 *MUST contain either result or error.
 **/
interface McpResponse {
  jsonrpc: string;
  id: number;
  result?: {
    contents?: Array<{ uri: string; mimeType?: string; text?: string }>;
    content?: Array<{ type: string; text?: string }>;
  };
  error?: { code: number; message: string };
}

/**
 * A platform measure instruction for a specific measure kind on a property.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️platformmeasureinstruction](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/PlatformMeasureInstruction)
 *MUST have instructions and optional mcp tools.
 **/
interface PlatformMeasureInstruction {
  instructions?: string;
  mcp?: {
    resources?: Array<{ id: string; instruction: string }>;
    tools?: Array<{ id: string; instruction: string; parameters?: Array<{ id: string; instruction: string }> }>;
  };
}

/**
 * A platform property with measure kind keys mapping to instructions.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️platformproperty](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/PlatformProperty)
 *MUST have id. Measure kinds (increase, decrease, etc.) are dynamic keys.
 **/
interface PlatformProperty {
  id: string;
  [measureKind: string]: string | PlatformMeasureInstruction | undefined;
}

/**
 * A platform with properties and their measure instructions.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️platform](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Platform)
 *MUST have an id.
 **/
interface Platform {
  id: string;
  properties?: PlatformProperty[];
}

/**
 * A clause within a compliance rule.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️clause](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Clause)
 *MUST have id and description.
 **/
interface Clause {
  id: string;
  description: string;
  status?: "compliant" | "violated" | "unknown";
  properties?: Array<{ id: string; value: string }>;
}

/**
 * A compliance rule belonging to a target.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️rule](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Rule)
 *MUST have id and description.
 **/
interface Rule {
  id: string;
  description: string;
  status?: "compliant" | "violated" | "unknown";
  clauses?: Clause[];
  measures?: string[];
  data?: Record<string, unknown>;
}

/**
 * A measure reference with an instruction for a specific level direction.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️levelmeasureref](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/LevelMeasureRef)
 *MUST have id and optional instruction.
 **/
interface LevelMeasureRef {
  id: string;
  instruction?: string;
}

/**
 * A level within a property, optionally with measures and instructions for raising/lowering.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️level](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Level)
 *MUST have a value. May have measures (lower/higher) and instructions (higher).
 **/
interface Level {
  value: string;
  name?: string;
  description?: string;
  measures?: { lower?: LevelMeasureRef[]; raise?: LevelMeasureRef[] };
  instructions?: { raise?: LevelMeasureRef[] };
}

/**
 * A property definition with canonical kind and associated measure_kinds.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️property](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Property)
 *MUST have id. Kind determines measure_kinds (e.g. number->increase/decrease, level->raise/lower).
 **/
interface Property {
  id: string;
  name?: string;
  kind?: string;
  measure_kinds?: string[];
  description?: string;
  url?: string;
  levels?: Level[];
  properties?: Property[];
  items?: Property;
  values?: string[];
}

/**
 * A compliance framework with properties and rules. General (not project-scoped).
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️framework](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Framework)
 *MUST have an id.
