// Entry point for the Electron renderer process mounting the coda React app.

// #endregion 🔖Header

// #region 🔖Renderer
// [🔬coda🖱️desktop💻renderer🔖renderer](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer)
// Electron renderer process that mounts the coda dashboard React app with window controls.
// MUST resolve the user identity before rendering the dashboard.
// MUST communicate with coda MCP server via the preload bridge.

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";

import { Tree, TreeItem, useCommandHotkey, useMediaQuery, i18next, initReactI18next } from "../../elements/ui";

import "./globals.css";

// Initialize i18next for elements.tsx components that use useTranslation().
// Without this, useTranslation() logs a warning and returns empty strings.
i18next.use(initReactI18next).init({
  lng: "en",
  fallbackLng: "en",
  interpolation: { escapeValue: false },
  resources: { en: { translation: {} } },
});

// #region 🔖Types
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types)
// TypeScript interfaces for coda domain models used in the renderer.
// Types MUST match the coda MCP server data structures.

declare global {
  interface Window {
    windowControls: {
      minimize(): Promise<void>;
      maximize(): Promise<void>;
      close(): Promise<void>;
    };
    os: {
      getUserId(): Promise<string>;
    };
    coda: {
      call(method: string, params?: Record<string, unknown>): Promise<McpResponse>;
      fetch(uri: string): Promise<McpResponse>;
      tool(name: string, args: Record<string, unknown>): Promise<McpResponse>;
      getConnectionStatus(): Promise<boolean>;
      onEvent(callback: (event: CodaEvent) => void): () => void;
      onConnectionStatus(callback: (connected: boolean) => void): () => void;
    };
    dialog: {
      openFolder(): Promise<string | null>;
    };
    project: {
      getPath(): Promise<string | null>;
      open(folder: string): Promise<{ success: boolean; error?: string }>;
      create(name: string, folder: string): Promise<{ success: boolean; error?: string }>;
    };
  }
}

/**
 * An event pushed from the coda sidecar process.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️codaevent](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/CodaEvent)
 *MUST have event kind, data, and timestamp.
 **/
interface CodaEvent {
  event: string;
  data: Record<string, unknown>;
  timestamp: number;
}

/**
 * MCP JSON-RPC response wrapper.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️mcpresponse](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/McpResponse)
 *MUST contain either result or error.
 **/
interface McpResponse {
  jsonrpc: string;
  id: number;
  result?: {
    contents?: Array<{ uri: string; mimeType?: string; text?: string }>;
    content?: Array<{ type: string; text?: string }>;
  };
  error?: { code: number; message: string };
}

/**
 * A platform measure instruction for a specific measure kind on a property.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️platformmeasureinstruction](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/PlatformMeasureInstruction)
 *MUST have instructions and optional mcp tools.
 **/
interface PlatformMeasureInstruction {
  instructions?: string;
  mcp?: {
    resources?: Array<{ id: string; instruction: string }>;
    tools?: Array<{ id: string; instruction: string; parameters?: Array<{ id: string; instruction: string }> }>;
  };
}

/**
 * A platform property with measure kind keys mapping to instructions.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️platformproperty](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/PlatformProperty)
 *MUST have id. Measure kinds (increase, decrease, etc.) are dynamic keys.
 **/
interface PlatformProperty {
  id: string;
  [measureKind: string]: string | PlatformMeasureInstruction | undefined;
}

/**
 * A platform with properties and their measure instructions.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️platform](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Platform)
 *MUST have an id.
 **/
interface Platform {
  id: string;
  properties?: PlatformProperty[];
}

/**
 * A clause within a compliance rule.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️clause](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Clause)
 *MUST have id and description.
 **/
interface Clause {
  id: string;
  description: string;
  status?: "compliant" | "violated" | "unknown";
  properties?: Array<{ id: string; value: string }>;
}

/**
 * A compliance rule belonging to a target.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️rule](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Rule)
 *MUST have id and description.
 **/
interface Rule {
  id: string;
  description: string;
  status?: "compliant" | "violated" | "unknown";
  clauses?: Clause[];
  measures?: string[];
  data?: Record<string, unknown>;
}

/**
 * A measure reference with an instruction for a specific level direction.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️levelmeasureref](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/LevelMeasureRef)
 *MUST have id and optional instruction.
 **/
interface LevelMeasureRef {
  id: string;
  instruction?: string;
}

/**
 * A level within a property, optionally with measures and instructions for raising/lowering.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️level](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Level)
 *MUST have a value. May have measures (lower/higher) and instructions (higher).
 **/
interface Level {
  value: string;
  name?: string;
  description?: string;
  measures?: { lower?: LevelMeasureRef[]; raise?: LevelMeasureRef[] };
  instructions?: { raise?: LevelMeasureRef[] };
}

/**
 * A property definition with canonical kind and associated measure_kinds.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️property](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Property)
 *MUST have id. Kind determines measure_kinds (e.g. number->increase/decrease, level->raise/lower).
 **/
interface Property {
  id: string;
  name?: string;
  kind?: string;
  measure_kinds?: string[];
  description?: string;
  url?: string;
  levels?: Level[];
  properties?: Property[];
  items?: Property;
  values?: string[];
}

/**
 * A compliance framework with properties and rules. General (not project-scoped).
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️framework](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Framework)
 *MUST have an id.
 **/
interface Framework {
  id: string;
  properties?: Property[];
  rules?: Rule[];
}

/**
 * Project configuration from .coda/project.json.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️project](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Project)
 *MUST have design and targets.
 **/
interface Project {
  design?: { id: string; mcp?: Record<string, unknown> };
  targets?: Array<{ id: string; llm?: unknown[] }>;
  error?: string;
}

/**
 * Run metadata.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️run](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Run)
 *MUST have an id.
 **/
interface Run {
  id?: string;
  started?: string;
  run_id?: string;
  error?: string;
}

/**
 * Iteration metadata.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️iteration](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Iteration)
 *MUST have an index.
 **/
interface Iteration {
  index?: number | string;
  targets?: string[];
  error?: string;
}

/**
 * Compliance report from an iteration.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️report](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Report)
 *MUST contain rules array.
 **/
interface Report {
  valid?: boolean;
  validations?: ValidationReport[];
  error?: string;
}

/**
 * Navigation page identifiers.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️page](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Page)
 *MUST enumerate all navigable pages.
 **/
type Page = "dashboard" | "config" | "runs" | "report" | "translations" | "actions" | "events";

