// #region 🔖ConfigPage
// [🔬coda🖱️desktop💻renderer🔖renderer🔖pages🔖configpage](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Pages/s/ConfigPage)

/**
 * Counts all properties recursively in a property tree.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖pages🔖configpage🛠️countproperties](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Pages/s/ConfigPage/d/i/countProperties)
 *MUST count the property itself plus all nested properties and items.
 **/
function countProperties(props: Property[]): number {
  let count = 0;
  for (const p of props) {
    count += 1;
    if (p.properties) count += countProperties(p.properties);
    if (p.items?.properties) count += countProperties(p.items.properties);
  }
  return count;
}

/**
 * Renders a single property with its kind badge, measure_kinds, and nested children.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖pages🔖configpage🛠️propertyview](repo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Pages/s/ConfigPage/d/i/PropertyView)
