                                            <div key={r.id} className="text-xs pl-2 border-l border-border-window">
                                              <span className="font-mono text-active-base">{r.id}</span>
                                              {r.instruction && <span className="text-muted-foreground"> — {r.instruction}</span>}
                                            </div>
                                          ))}
